"""Slide definitions for the 'MAM is a dataset' deck.

Slides
------
title-card              "MAM is a dataset" / "(MAM is not an edition)"
psalm-5v9-sources       Composite of five Psalm 5:9 source screenshots
psalm-15v1-qamats       Syntax-colored JSON of the מ:קמץ template in Psalm 15:1
"""

import pathlib

from PIL import ImageFont

from py_misc import json_snippet_browser
from slide_generator import composite_img_sources, slide_render

DECK_NAME = "mam-is-a-dataset"
IMAGES_DIR = pathlib.Path("misc/mam-is-a-dataset/img")

# Teal gradient shared across all slides in this deck
_TOP_RGB = (13, 94, 87)
_BOT_RGB = (8, 61, 56)


def _gradient():
    return slide_render.make_gradient(_TOP_RGB, _BOT_RGB)


def render_title_card():
    """Render slide-title-card.png."""
    font_bold = ImageFont.truetype(str(slide_render.FONT_DIR / "arialbd.ttf"), size=180)
    font_reg = ImageFont.truetype(str(slide_render.FONT_DIR / "arial.ttf"), size=96)
    lines = [
        ("MAM is a dataset", font_bold, (255, 255, 255)),
        ("(MAM is not an edition)", font_reg, (200, 232, 228)),
    ]
    img = _gradient()
    slide_render.draw_centered_lines(img, lines, gap_after=[80, 0])
    dest = IMAGES_DIR / "slide-title-card.png"
    dest.parent.mkdir(parents=True, exist_ok=True)
    img.save(dest)
    slide_render.write_provenance(dest, DECK_NAME, "title-card")
    print(f"Saved {dest} {img.size}")


_PSALM_15V1_JSON = pathlib.Path(
    "misc/mam-is-a-dataset/img-sources/Psalm 15v1 באהלך.json"
)
_PSALM_15V1_PHONETIC = pathlib.Path(
    "misc/mam-is-a-dataset/img-sources/Psalm 15v1 באהלך phonetic.png"
)


def render_psalm_5v9_sources():
    """Render slide-psalm-5v9-sources.png."""
    composite_img_sources.render_psalm_5v9_sources(IMAGES_DIR)


def render_psalm_15v1_qamats():
    """Render slide-psalm-15v1-qamats.png with syntax-colored JSON."""
    json_snippet_browser.render_json_snippet_browser(
        IMAGES_DIR,
        DECK_NAME,
        _PSALM_15V1_JSON,
        "psalm-15v1-qamats",
        top_rgb=_TOP_RGB,
        bot_rgb=_BOT_RGB,
        companion_image_path=_PSALM_15V1_PHONETIC,
    )


ALL_SLIDES = {
    "title-card": render_title_card,
    "psalm-5v9-sources": render_psalm_5v9_sources,
    "psalm-15v1-qamats": render_psalm_15v1_qamats,
}
